DO $$ DECLARE definition text; BEGIN SELECT pg_get_viewdef('public.commercial_orders'::regclass,true) INTO definition; definition := replace(definition, 'auth.uid() = client_id', 'public.owns_client_registration(client_id)'); definition := replace(definition, 'w.client_id = auth.uid()', 'public.owns_client_registration(w.client_id)'); EXECUTE 'CREATE OR REPLACE VIEW public.commercial_orders WITH (security_barrier=true) AS ' || definition; END $$;